:root {
  --paper: #fff8e8;
  --ink: #23323a;
  --clay: #d85c42;
}

.dance-card {
  width: 460px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 18px;
}

.card-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 18px 12px;
  background: var(--clay);
}

.emblem {
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  background: var(--paper);
  border-radius: 12px;
  font-size: 22px;
}

.card-head section {
  min-width: 0;
}

.eyebrow,
.card-head h1 {
  margin: 0;
}

.eyebrow {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.card-head h1 {
  font-size: 21px;
  line-height: 1.15;
}

.session {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 13px 18px;
  border-top: 2px solid var(--ink);
  font-size: 14px;
}

.session span {
  font-size: 13px;
}

.card-foot {
  display: flex;
  justify-content: space-between;
  padding: 9px 18px;
  color: var(--paper);
  background: var(--ink);
  font-size: 13px;
  font-weight: 700;
}

.admit {
  color: var(--clay);
}
